package gg.neonnexus.smpplatform.integrations.skript;
import ch.njol.skript.lang.Effect; import ch.njol.skript.lang.Expression; import ch.njol.skript.lang.SkriptParser.ParseResult; import ch.njol.util.Kleenean; import org.bukkit.entity.Player; import org.bukkit.event.Event;
public final class EffNexusNotification extends Effect { private Expression<String> message; private Expression<Player> players; @SuppressWarnings("unchecked") @Override public boolean init(Expression<?>[] x,int m,Kleenean d,ParseResult p){message=(Expression<String>)x[0];players=(Expression<Player>)x[1];return true;} @Override protected void execute(Event e){String text=message.getSingle(e);if(text!=null)for(Player p:players.getArray(e))NexusSkriptRegistry.bridge().sendNotification(p.getUniqueId(),text);} @Override public String toString(Event e,boolean d){return "nexus notification";} }
